#include <QTRSensors.h>

QTRSensors qtr;
const uint8_t SENSORS[8] = {A0, A1, A2, A3, A4, A5, 11, 12};   // OUT1-OUT8: any digital pin can time an RC output
uint16_t values[8];
const int PWMA = 5, AIN1 = 7, AIN2 = 8, STBY = 9, BIN1 = 10, BIN2 = 4, PWMB = 6;
const int BASE = 150;

void motors(int left, int right) {   // both wheels forward, speed from 0 to 255
  digitalWrite(AIN1, HIGH); digitalWrite(AIN2, LOW); analogWrite(PWMA, constrain(left, 0, 255));
  digitalWrite(BIN1, HIGH); digitalWrite(BIN2, LOW); analogWrite(PWMB, constrain(right, 0, 255));
}

void setup() {
  Serial.begin(9600);
  qtr.setTypeRC();
  qtr.setSensorPins(SENSORS, 8);
  qtr.setEmitterPin(2);          // LEDON: the library turns the IR LEDs on for each read
  for (int p = 4; p <= 10; p++) pinMode(p, OUTPUT);
  digitalWrite(STBY, HIGH);
  for (int i = 0; i < 100; i++) {   // sweep the array over the tape now: each sensor learns its own white and black
    qtr.calibrate();
    delay(20);
  }
}

void loop() {
  uint16_t pos = qtr.readLineBlack(values);
  int error = (int)pos - 3500;
  int turn = error / 20;
  motors(BASE + turn, BASE - turn);
  delay(20);
}

